<?php require __DIR__.'/../db.php'; $db=connect_db($config['db']); ensure_core_tables($db); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $st=$db->prepare('INSERT INTO subjects(id,code,subject_name,max_mark,pass_mark,display_order) VALUES(:id,:c,:n,:m,:p,:o) ON DUPLICATE KEY UPDATE subject_name=VALUES(subject_name),max_mark=VALUES(max_mark),pass_mark=VALUES(pass_mark),display_order=VALUES(display_order)'); $st->execute(['id'=>(int)$_POST['id'],'c'=>trim($_POST['code']),'n'=>trim($_POST['subject_name']),'m'=>(float)$_POST['max_mark'],'p'=>(float)$_POST['pass_mark'],'o'=>(int)$_POST['display_order']]); $msg='Subject saved'; } include __DIR__.'/../layout/header.php'; include __DIR__.'/../layout/sidebar.php'; ?>
<h3>Add Subject</h3><p class="text-success"><?= h($msg) ?></p><form method="post" class="row g-2"><div class="col"><input class="form-control" name="id" placeholder="ID" required></div><div class="col"><input class="form-control" name="code" placeholder="Code" required></div><div class="col"><input class="form-control" name="subject_name" placeholder="Name" required></div><div class="col"><input class="form-control" name="max_mark" value="50" required></div><div class="col"><input class="form-control" name="pass_mark" value="18" required></div><div class="col"><input class="form-control" name="display_order" value="1" required></div><div class="col-12"><button class="btn btn-primary">Save</button></div></form>
